package com.hoteluq.service;
import com.hoteluq.model.*;import com.hoteluq.repository.*;import com.hoteluq.pattern.structural.PaymentGateway;import com.hoteluq.pattern.behavioral.Observer.ReservationObserver;import com.hoteluq.exception.BusinessException;import java.util.*;
public class ReservationService {private final Repository<Reservation,String> reservations;private final List<ReservationObserver> observers=new ArrayList<>();public ReservationService(Repository<Reservation,String> r){reservations=r;}public void addObserver(ReservationObserver o){observers.add(o);}public void confirmReservation(Reservation r,PaymentGateway payment){if(!isAvailable(r.getRoom(),r.getCheckIn(),r.getCheckOut()))throw new BusinessException("La habitación no está disponible para esas fechas");payment.pay(r.getTotal(),"Reserva HotelUQ");r.confirm();reservations.save(r);notifyObservers(r,"RESERVA CONFIRMADA");}public boolean isAvailable(Room room,java.time.LocalDate in,java.time.LocalDate out){return reservations.findAll().stream().filter(r->r.getRoom().getNumber().equals(room.getNumber())).filter(r->r.getStatus()!=com.hoteluq.model.enums.ReservationStatus.CANCELLED).noneMatch(r->in.isBefore(r.getCheckOut())&&out.isAfter(r.getCheckIn()));}public List<Reservation> all(){return reservations.findAll();}public void cancel(Reservation r,Wallet wallet,com.hoteluq.pattern.behavioral.strategy.CancellationPolicy policy,boolean byHotel){if(r.getStatus()!=com.hoteluq.model.enums.ReservationStatus.CONFIRMED)throw new BusinessException("Solo se cancelan reservas confirmadas");r.cancel();double refund=(byHotel?new com.hoteluq.pattern.behavioral.strategy.HotelCancellationPolicy():policy).refund(r.getTotal(),r.getCheckIn().atStartOfDay(),java.time.LocalDateTime.now());if(refund>0){r.markRefunded();wallet.refund(refund,"Reembolso reserva "+r.getId());}notifyObservers(r,"RESERVA CANCELADA; reembolso: $"+refund);}private void notifyObservers(Reservation r,String e){observers.forEach(o->o.onReservationChanged(r,e));}}
